From 90e338f239f9c2afb9a7fe968584b332ef43626e Mon Sep 17 00:00:00 2001
From: Andrew Bettison <andrew@servalproject.org>
Date: Thu, 17 May 2018 10:57:34 +0930
Subject: [PATCH] Fix compile error introduced in c2103e3 (fixes #138)


diff --git a/overlay_mdp.c b/overlay_mdp.c
index dc0a158c..07311750 100644
--- a/overlay_mdp.c
+++ b/overlay_mdp.c
@@ -1439,7 +1439,7 @@ static void mdp_interface_packet(struct socket_address *client, struct mdp_heade
 	  break;
 	}
 	bcopy(ob_get_bytes_ptr(payload, addr.addrlen), addr.raw, addr.addrlen);
-	struct network_destination *destination = create_unicast_destination(&addr, state->interface);
+	struct network_destination *destination = create_unicast_destination(&addr, interface);
 	if (!destination)
 	  break;
 	overlay_send_probe(NULL, destination, OQ_ORDINARY);
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the use of an incorrect variable (`state->interface`) instead of the correct variable (`interface`) when calling the `create_unicast_destination` function. This mismatch led to a compile error, as the expected argument type was not met, preventing the code from compiling successfully.

        Commit message:
        Fix compile error introduced in c2103e3 (fixes #138)  

        Patch:

 static void mdp_interface_packet(struct socket_address *client, struct mdp_header *UNUSED(header), 
   struct overlay_buffer *payload){
   int msg_type = ob_get(payload);
   switch (msg_type){
     case MDP_INTERFACE_UP:{
       struct config_network_interface ifconfig;
       cf_dfl_config_network_interface(&ifconfig);

       struct cf_om_node *conf_node = NULL;
       int result = cf_om_parse("ext", (char*)ob_current_ptr(payload), ob_remaining(payload), &conf_node);
       if (result == CFOK || result == CFEMPTY){
 	result = conf_node ? cf_opt_config_network_interface(&ifconfig, conf_node) : CFEMPTY;
       }

       if ((result == CFOK || result == CFEMPTY)
 	&& ifconfig.socket_type != SOCK_EXT){
 	// TODO log nice warning, pick right result code
 	result |= CFSUB(CFUNSUPPORTED);
       }

       if ((result == CFOK || result == CFEMPTY)
 	&& ifconfig.match.patc == 0){
 	ifconfig.match.patc=1;
 	strncpy_nul(ifconfig.match.patv[0], "ext", INTERFACE_NAME_STRLEN);
       }

       if (result == CFOK || result == CFEMPTY){
 	struct overlay_interface *interface=overlay_interface_find_name_file_addr(NULL, NULL, client);
 	if (!interface){
 	  overlay_interface_init(ifconfig.match.patv[0], NULL, OVERLAY_INTERFACE_UNKNOWN, client, NULL, NULL, &ifconfig);
 	}else{
 	  // reconfigure the interface with new / current settings
 	  if (overlay_interface_configure(interface, &ifconfig)==-1)
 	    overlay_interface_close(interface);
 	}
       }
     }break;
     case MDP_INTERFACE_DOWN:{
       struct overlay_interface *interface=overlay_interface_find_name_file_addr(NULL, NULL, client);
       if (interface)
 	overlay_interface_close(interface);
     }break;
     case MDP_INTERFACE_PEER:{
       // some form of external peer discovery has occurred
       struct overlay_interface *interface=overlay_interface_find_name_file_addr(NULL, NULL, client);
       if (interface){
 	// queue a unicast probe packet to this address
 	struct socket_address addr;
 	addr.addrlen = ob_get(payload);
 	if ((size_t)addr.addrlen > sizeof(addr)){
 	  WARNF("Malformed MDP_INTERFACE_RECV header, %u bytes is too large", (unsigned)addr.addrlen);
 	  break;
 	}
 	bcopy(ob_get_bytes_ptr(payload, addr.addrlen), addr.raw, addr.addrlen);
-	struct network_destination *destination = create_unicast_destination(&addr, state->interface);
+	struct network_destination *destination = create_unicast_destination(&addr, interface);
 	if (!destination)
 	  break;
 	overlay_send_probe(NULL, destination, OQ_ORDINARY);
 	release_destination_ref(destination);
       }
       break;
     }
     case MDP_INTERFACE_RECV:{
       struct overlay_interface *interface=overlay_interface_find_name_file_addr(NULL, NULL, client);
       if (interface){
 	struct socket_address addr;
 	addr.addrlen = ob_get(payload);
 	if ((size_t)addr.addrlen > sizeof(addr)){
 	  WARNF("Malformed MDP_INTERFACE_RECV header, %u bytes is too large", (unsigned)addr.addrlen);
 	  break;
 	}
 	bcopy(ob_get_bytes_ptr(payload, addr.addrlen), addr.raw, addr.addrlen);
 	packetOkOverlay(interface, ob_current_ptr(payload), ob_remaining(payload), &addr);
       }
       break;
     }
   }
 }



